  select array_agg(id) into matches from public.venues where city='nyc' and not coalesce(is_demo,false)
   and (id=nullif(item->>'venueId','')::uuid or google_place_id=item->>'googlePlaceId'
     or regexp_replace(lower(name),'[^a-z0-9]','','g')=regexp_replace(lower(item->>'name'),'[^a-z0-9]','','g'));
  if cardinality(matches)>1 then raise exception 'Ambiguous catalog match for %',item->>'name';end if;
  if cardinality(matches)=1 then
   target:=matches[1];
   update public.venues set google_place_id=item->>'googlePlaceId',lat=(item->>'lat')::float8,lng=(item->>'lng')::float8,
    leaderboard_category=item->>'category',leaderboard_exclusion_reason=case when item->>'accessLabel'='Members only' then 'members_only_editorial_exception' else null end where id=target;
  else
   insert into public.venues(name,city,neighborhood,type,google_place_id,lat,lng,is_demo,leaderboard_category,leaderboard_exclusion_reason,popularity_rank)
   values(item->>'name','nyc',item->>'neighborhood',item->>'type',item->>'googlePlaceId',(item->>'lat')::float8,(item->>'lng')::float8,false,item->>'category',null,999);
  end if;
 end loop;
end; $hot_spots$;
commit;
